-- Local dev seed (fictional data). Run: npm run db:seed
DELETE FROM votes; DELETE FROM checkins; DELETE FROM reports; DELETE FROM saves; DELETE FROM popup_images; DELETE FROM karma_log; DELETE FROM popups; DELETE FROM sessions; DELETE FROM subscribers; DELETE FROM audit_log; DELETE FROM users;



UPDATE popups SET report_weight = 3.6 WHERE id = 'sneaker';

-- Real vote, check-in rows behind the cached counts above, so recomputing keeps them.
WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
SELECT 'seed_v' || n, 'voter' || n || '@spotted.dev', 'Voter ' || n, 'user', 20, 0, 1, CAST(strftime('%s','now') AS INTEGER)*1000 - 90*86400000 FROM s;

WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
SELECT 'seed_v' || s.n, p.id, 'existence', 1, p.exist_pos * 1.0 / (p.voter_count - (p.exist_neg > 0)), 'seedip' || s.n, CAST(strftime('%s','now') AS INTEGER)*1000
FROM popups p JOIN s ON s.n <= p.voter_count - (p.exist_neg > 0) WHERE p.exist_pos > 0;

SELECT 'seed_v160', id, 'existence', -1, exist_neg, 'seedip160', CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups WHERE exist_neg > 0;

-- quality votes; the poster's own upvote is one of quality_pos
WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
SELECT 'seed_v' || s.n, p.id, 'quality', CASE WHEN s.n <= p.quality_pos - 1 THEN 1 ELSE -1 END, 1, CAST(strftime('%s','now') AS INTEGER)*1000
FROM popups p JOIN s ON s.n <= p.quality_pos - 1 + p.quality_neg;
SELECT created_by, id, 'quality', 1, 1, CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups WHERE quality_pos > 0;

WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
SELECT 'seed_v' || s.n, p.id, 40, 1, CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups p JOIN s ON s.n <= p.checkin_count;
